for t in -1 0 2; do
python3 - <<EOF
tickets = $t
if tickets < 0:
    print(tickets, "Invalid quantity")
else:
    if tickets == 0:
        print(tickets, "No booking")
    else:
        print(tickets, f"Booked: {tickets}")
EOF
done
